import csv
import sys
reader = csv.DictReader(sys.stdin)
totals = {}
rejected = 0
for row in reader:
    row = {k.strip(): v.strip() for k, v in row.items()}
    try:
        qty = int(row['qty'])
        price = float(row['unit_price'])
    except ValueError:
        rejected += 1
        continue
    key = (row['date'][:7], row['store'].title())
    totals[key] = totals.get(key, 0.0) + qty * price
print('month,store,revenue')
for (month, store) in sorted(totals):
    print(f'{month},{store},{totals[(month, store)]:.2f}')
print(f'rejected {rejected}')

