allowed = set(input().split())
n = int(input())
names = ['duplicate_id', 'missing_email', 'invalid_email', 'invalid_age', 'invalid_country']
counts = {k: 0 for k in names}
seen = set()
clean = 0

def valid_email(e):
    if e.count('@') != 1:
        return False
    return '.' in e.split('@')[1]

for _ in range(n):
    rid, email, age, country = input().split(',')
    found = []
    if rid in seen:
        found.append('duplicate_id')
    seen.add(rid)
    if email == '':
        found.append('missing_email')
    elif not valid_email(email):
        found.append('invalid_email')
    if not age.isdigit() or int(age) > 120:
        found.append('invalid_age')
    if country not in allowed:
        found.append('invalid_country')
    for f in found:
        counts[f] += 1
    if not found:
        clean += 1
for k in names:
    print(k, counts[k])
print('clean_rows', clean)
print(f'quality_score {clean / n * 100:.1f}%')
